Neon PostgreSQL (<code>pgvector</code> + FTS) Neo4j Knowledge Graph Schema <p>Initialized automatically at startup by <code>app/database.py</code> (reference schema in <code>sql/schema.sql</code>).</p> sql/schema.sql<pre><code>CREATE EXTENSION IF NOT EXISTS vector;

-- 1. Users table (Neon PostgreSQL Authentication)
CREATE TABLE IF NOT EXISTS users (
    user_id TEXT PRIMARY KEY,
    email TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    password_hash TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_Users_Email ON users(email);

-- 2. Documents metadata table
CREATE TABLE IF NOT EXISTS documents (
    document_id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    filename TEXT NOT NULL,
    file_type TEXT NOT NULL,
    chunks_count INTEGER DEFAULT 0,
    entities_count INTEGER DEFAULT 0,
    relationships_count INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_Documents_User ON documents(user_id);

-- 3. Document chunks table with 768-dim Gemini embeddings
CREATE TABLE IF NOT EXISTS document_chunks (
    chunk_id TEXT PRIMARY KEY,
    document_id TEXT NOT NULL REFERENCES documents(document_id) ON DELETE CASCADE,
    user_id TEXT NOT NULL,
    filename TEXT NOT NULL,
    chunk_index INTEGER NOT NULL,
    content TEXT NOT NULL,
    embedding VECTOR(768) NOT NULL,
    metadata JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- B-Tree tenant &amp; join indexes
CREATE INDEX IF NOT EXISTS idx_Chunks_User ON document_chunks(user_id);
CREATE INDEX IF NOT EXISTS idx_Chunks_Document ON document_chunks(document_id);

-- HNSW index for fast approximate cosine similarity search
CREATE INDEX IF NOT EXISTS idx_Chunks_Embedding_HNSW
    ON document_chunks USING hnsw (embedding vector_cosine_ops);

-- GIN index for fast English Full-Text Search (tsvector)
CREATE INDEX IF NOT EXISTS idx_Chunks_Content_FTS
    ON document_chunks USING gin (to_tsvector('english', content));
</code></pre> <pre><code>erDiagram
